    "artigoNum": 170,
    "diploma": "Código Penal (Decreto-Lei 2.848/40)",
    "dispositivo": "Art. 170",
    "texto": "Nos crimes previstos neste art. 155, § 2o . Outras Fraudes Estelionato",
    "explicacao": "Tipicidade penal, dosimetria e tutela de bens jurídicos tutelados pelo Estado.",
    "eixo": "Direito Penal",
    "disciplina": "Direito Penal",
    "fonteOficial": "Senado Federal / Planalto (Edição 2026)",
